       <div class="mutation-circuit"><h3>Assembler la recette</h3><div class="mutation-slots"><button v-for="component in recipe" :key="component.key" :data-corruption-slot="component.key" :class="{'is-filled':filled.includes(component.key),'is-target':drag?.key===component.key}" :disabled="busy" :aria-label="component.name+(filled.includes(component.key)?', retirer de la recette':', emplacement vide')" @click="remove(component.key)"><bag-item-icon :item-key="component.key" pocket="treasures"/><strong>×{{ component.quantity }}</strong><small>{{ filled.includes(component.key)?'Prêt':'Déposer ici' }}</small></button></div><div class="mutation-core"><bag-item-icon :item-key="'cmod_'+({move:'move_53',ability:'ability_levitate',type:'type_fire',combat:'offense_fire'}[panel.station])" pocket="corruption"/><span>{{ ready?'Recette complète':'Quatre composants nécessaires' }}<small>{{ panel.station==='combat'?'L’échec consomme tous les composants.':panel.station==='type'?'Module du type choisi ; mutation à l’installation.':'Résultat aléatoire, visible après fabrication.' }}</small></span></div></div>
      </div>
