     </template>
     <div v-else class="mutation-result" :class="{'mutation-failed':!result.created}" role="status" data-corruption-result><bag-item-icon v-if="result.item" :item-key="result.item.key" pocket="corruption"/><span v-else class="mutation-broken" aria-hidden="true">◇</span><small>{{ result.created?'SYNTHÈSE RÉUSSIE':'SYNTHÈSE ÉCHOUÉE' }}</small><h3>{{ result.created?result.item.name:'Les cristaux se sont désagrégés.' }}</h3><p>{{ result.created?effect(result.item):'Aucun module créé. Les composants de cette tentative ont été consommés.' }}</p><p v-if="result.item?.corruptionModule.family==='move'" class="mutation-move-description">{{ moveStats(result.item.corruptionModule.move) }} · {{ moveDescription(result.item.corruptionModule.move) }}</p><p v-if="result.item?.corruptionModule.family==='ability'" class="mutation-move-description">{{ abilityDescription(result.item.corruptionModule.ability) }}</p><small v-if="result.created">Retrouve ton module dans le sac, rubrique Corruption.</small></div>
