import reference from '@/data/pokemonReference.fr.json';
export default{components:{BagItemIcon,MenuHelp},props:{panel:Object,items:Array,command:Function},data(){return{helpOpen:false,poolOpen:false,poolSearch:'',type:'Normal',filled:[],drag:null,result:null,error:'',busy:false,uncertain:false,requestId:crypto.randomUUID(),previous:null,ignoreClickUntil:0};},computed:{guideSteps(){return corruptionWorkbenchHelp({family:this.station.key,typeLabel:this.typeName(this.type),recipe:this.recipe,statPenalties:balance.statPenalties,defenseMultiplier:balance.defenseMultiplier,abilityCount:this.totalAbilities,unlocked:!!this.panel.unlocked});},totalAbilities(){return abilityPools[this.type]?.length||0;},possibleAbilities(){const q=this.poolSearch.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();return (abilityPools[this.type]||[]).filter(a=>[a.name,a.ability,reference.abilities[a.ability],...a.species.map(s=>s.name)].join(' ').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(q));},station(){return CORRUPTION_FAMILIES.find(s=>s.key===this.panel.station)||CORRUPTION_FAMILIES[0];},types(){return ['Normal','Fire','Water','Electric','Grass','Ice','Fighting','Poison','Ground','Flying','Psychic','Bug','Rock','Ghost','Dragon','Dark','Steel','Fairy'];},recipe(){return recipeFor(this.panel.station,this.type);},ready(){return this.recipe.every(c=>this.filled.includes(c.key)&&this.stock(c.key)>=c.quantity);},help(){return{move:'Extraire une attaque aléatoire du type de la plaque. Cette CS sera compatible avec toutes les espèces.',ability:'Extraire un talent d’une espèce de ce type. Les talents proposés ont un effet disponible en combat, sans forme exclusive à une espèce.',type:'Un module qui modifie les types du Pokémon sans changer son movepool classique. Cette synthèse demande davantage de cristaux et de plaques.',combat:`Créer au hasard un module offensif (+20 %) ou défensif (−${Math.round((1-balance.defenseMultiplier)*100)} %) du type choisi. Une tentative sur deux échoue.`}[this.panel.station];}},mounted(){this.previous=document.activeElement;this.$refs.close.focus();const first=this.types.find(t=>this.stock('dark_plate_'+t.toLowerCase())>0);if(first)this.type=first;window.addEventListener('pointermove',this.moveDrag,{passive:false});window.addEventListener('pointerup',this.endDrag);window.addEventListener('pointercancel',this.cancelDrag);},beforeDestroy(){window.removeEventListener('pointermove',this.moveDrag);window.removeEventListener('pointerup',this.endDrag);window.removeEventListener('pointercancel',this.cancelDrag);this.previous?.isConnected&&this.previous.focus({preventScroll:true});},methods:{openHelp(){if(this.busy)return;this.cancelDrag();this.helpOpen=true;},closePanel(){if(this.helpOpen){this.helpOpen=false;return;}if(!this.busy)this.$emit('close');},abilityName:n=>localizeAbilityName(n,'fr'),typeName:localizeTypeName,typeStyle:typeBadgeStyle,effect:moduleEffect,moveStats(name){const m=reference.moves[name]||{};return`${{physical:'Physique',special:'Spéciale',status:'Statut'}[m.category]||'—'} · puissance ${m.power||'—'} · précision ${m.accuracy||'—'} · ${m.pp||'—'} PP`;},moveDescription(name){return reference.moves[name]?.description||'';},abilityDescription(name){return reference.abilities[name]||'';},stock(key){return Number(this.items?.find(i=>i.key===key)?.quantity)||0;},reset(){if(this.busy)return;this.filled=[];this.result=null;this.error='';this.uncertain=false;this.requestId=crypto.randomUUID();},add(key){const c=this.recipe.find(c=>c.key===key);if(!this.busy&&c&&this.stock(key)>=c.quantity&&!this.filled.includes(key))this.filled.push(key);},remove(key){if(!this.busy)this.filled=this.filled.filter(k=>k!==key);},addByClick(key){if(performance.now()>this.ignoreClickUntil)this.add(key);},startDrag(e,key){if(this.busy||e.button!==0)return;this.drag={key,id:e.pointerId,startX:e.clientX,startY:e.clientY,x:e.clientX,y:e.clientY,moving:false};e.currentTarget.setPointerCapture?.(e.pointerId);},moveDrag(e){if(!this.drag||e.pointerId!==this.drag.id)return;const d=this.drag;d.x=e.clientX;d.y=e.clientY;if(Math.hypot(d.x-d.startX,d.y-d.startY)>6)d.moving=true;if(d.moving)e.preventDefault();},endDrag(e){if(!this.drag||e.pointerId!==this.drag.id)return;const d=this.drag;this.drag=null;if(!d.moving)return;this.ignoreClickUntil=performance.now()+250;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-corruption-slot]');if(target?.dataset.corruptionSlot===d.key)this.add(d.key);},cancelDrag(){this.drag=null;},async craft(){if(this.busy||!this.uncertain&&!this.ready)return;this.busy=true;this.error='';try{const result=await this.command('corruption:craft',{requestId:this.requestId,recipeVersion:CORRUPTION_RECIPE_VERSION,family:this.panel.station,type:this.type});if(!result.success){this.error=result.message;this.uncertain=!!result.uncertain;return;}this.result=result;this.uncertain=false;this.filled=[];this.$emit('crafted',result);}catch(e){this.error=e.message;this.uncertain=true;}finally{this.busy=false;}},trap(e){if(this.helpOpen)return;const n=[...this.$refs.dialog.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),[tabindex="0"]')].filter(n=>n.getClientRects().length),a=n[0],b=n.at(-1);if(e.shiftKey&&document.activeElement===a){e.preventDefault();b?.focus();}if(!e.shiftKey&&document.activeElement===b){e.preventDefault();a?.focus();}}}};
</script>
