}.mutation-resource{display:flex;width:100%;align-items:center;gap:12px;padding:12px;margin-top:9px;text-align:left;touch-action:none}.mutation-resource>span:nth-child(2){flex:1;min-width:0}.mutation-resource strong{font-size:12px;display:block}.mutation-resource small{font-size:10px;color:var(--journal-muted);display:block;margin-top:3px}.mutation-resource-add{font-size:20px;color:#9a6bb5}.mutation-slots{display:grid;grid-template-columns:1fr 1fr;gap:10px}.mutation-slots button{min-height:96px;display:grid;justify-items:center;gap:5px;border:2px dashed #b09ac0;background:var(--journal-soft);padding:9px;min-width:0}.mutation-slots .bag-object-icon{width:34px;height:34px;opacity:.45}.mutation-slots small{font-size:10px;color:var(--journal-muted)}.mutation-slots .is-filled{border-style:solid;background:var(--journal-selected)}.mutation-slots .is-filled .bag-object-icon{opacity:1}.mutation-slots .is-target{outline:2px solid #ae7ccd;outline-offset:2px}.mutation-core{display:flex;gap:12px;align-items:center;padding:14px;margin-top:14px;border:1px solid #a68ab9;border-radius:10px;background:var(--journal-card);font-weight:700;font-size:12px}.mutation-core small{display:block;color:var(--journal-muted);font-weight:400;font-size:10px;margin-top:4px}.mutation-caution{font-size:11px;margin:20px 0 0;color:var(--journal-muted)}footer{padding:14px 24px;border-top:1px solid var(--journal-border);background:var(--journal-card);display:flex;align-items:center;justify-content:space-between;gap:14px}footer>span{font-size:11px;color:var(--journal-muted)}.mutation-primary{background:#805699;color:#fff;border-color:#9d7ab0;font-weight:700}.mutation-error{font-size:12px;color:var(--journal-danger);padding:10px 24px;margin:0}.mutation-result{text-align:center;padding:15px 0}.mutation-result>.bag-object-icon{width:64px;height:64px;margin:0 auto 14px}.mutation-result>small{font-size:10px;color:#9264ad;letter-spacing:.08em}.mutation-result h3{font:24px Georgia,serif;color:var(--journal-heading);margin:10px 0}.mutation-result p{font-size:13px}.mutation-move-description{max-width:55ch;margin:12px auto;color:var(--journal-muted)}.mutation-broken{font-size:58px;color:#aa6b80;display:block}.mutation-drag{position:fixed;z-index:3600;pointer-events:none;transform:translate(-50%,-85%);background:var(--journal-card);padding:12px;border:2px solid #a777c0;border-radius:12px;box-shadow:var(--journal-shadow);display:flex;align-items:center;gap:8px;color:var(--journal-ink)}.mutation-locked{padding:30px 0;font:17px/1.8 Georgia,serif;max-width:55ch}
